function countSpellings(s: string, t: string): number {
  const MOD = 1_000_000_007;
  const go = (i: number, j: number): number => {
    if (j === t.length) return 1;                  // the whole word is spelled
    if (s.length - i < t.length - j) return 0;     // not enough letters left
    let ways = go(i + 1, j);                       // delete s[i]
    if (s[i] === t[j]) ways += go(i + 1, j + 1);   // keep s[i] as t[j]
    return ways % MOD;
  };
  return go(0, 0);
}

