function countSpellings(s: string, t: string): number {
  const MOD = 1_000_000_007;
  const n = s.length, m = t.length;
  const dp: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = 0; i <= n; i++) dp[i][0] = 1; // the empty word: delete everything
  for (let i = 1; i <= n; i++)
    for (let j = 1; j <= m; j++) {
      dp[i][j] = dp[i - 1][j];
      if (s[i - 1] === t[j - 1]) dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
    }
  return dp[n][m];
}

