function countSpellings(s: string, t: string): number {
  const MOD = 1_000_000_007;
  const m = t.length;
  const row = new Array(m + 1).fill(0);
  row[0] = 1;
  for (const c of s)
    for (let j = m; j >= 1; j--)               // downward: row[j - 1] is still the old value
      if (c === t[j - 1]) row[j] = (row[j] + row[j - 1]) % MOD;
  return row[m];
}

